-- V35: fully reworked lesson quizzes. Each lesson has its own authored question set.
begin;
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Первый эфир — базовые принципы торговли». Ситуация: Трейдер видит сигнал, но не может объяснить, почему именно сейчас вход соответствует его плану. Что из перечисленного лучше всего соответствует теме «базовые принципы торговли»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"отложить вход до появления понятного основания","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: решение должно опираться на понятную логику, а не на случайный вход."},{"id":"q2","type":"multi_select","question":"В уроке «Первый эфир — базовые принципы торговли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"отложить вход до появления понятного основания","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"решение должно опираться на понятную логику, а не на случайный вход","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «базовые принципы торговли» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Первый эфир — базовые принципы торговли». Для темы «базовые принципы торговли» можно пропустить проверку ситуации, если уже выполнено условие: отложить вход до появления понятного основания.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «базовые принципы торговли» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Первый эфир — базовые принципы торговли». Какое действие здесь является главным нарушением логики темы «базовые принципы торговли»?","options":[{"value":"A","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно базовые принципы торговли перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: решение должно опираться на понятную логику, а не на случайный вход."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «базовые принципы торговли» в уроке «Первый эфир — базовые принципы торговли»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Первый эфир посвящён базовым принципам торговли и переходу от случайных входов к понятной логике решения.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='basics-first-live';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Свечи, которые дают деньги». Ситуация: После сильного движения появилась свеча с маленьким телом и длинной тенью. Что из перечисленного лучше всего соответствует теме «японские свечи»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сопоставить свечу с предшествующим движением и дождаться развития реакции","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей."},{"id":"q2","type":"multi_select","question":"В уроке «Свечи, которые дают деньги» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сопоставить свечу с предшествующим движением и дождаться развития реакции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «японские свечи» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Свечи, которые дают деньги». Для темы «японские свечи» можно пропустить проверку ситуации, если уже выполнено условие: сопоставить свечу с предшествующим движением и дождаться развития реакции.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «японские свечи» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Свечи, которые дают деньги». Какое действие здесь является главным нарушением логики темы «японские свечи»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно японские свечи перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «японские свечи» в уроке «Свечи, которые дают деньги»?","options":[{"value":"A","label":"Урок посвящён японским свечам, чтению их формы, настроению рынка и логике входа.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='candles-third-live';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Горизонтальные уровни». Ситуация: На одном ценовом участке рынок уже несколько раз реагировал, но текущий подход к нему очень быстрый. Что из перечисленного лучше всего соответствует теме «горизонтальные уровни»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценить реакцию цены в области и контекст подхода","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии."},{"id":"q2","type":"multi_select","question":"В уроке «Горизонтальные уровни» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценить реакцию цены в области и контекст подхода","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «горизонтальные уровни» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Горизонтальные уровни». Если выполнить условие «оценить реакцию цены в области и контекст подхода», тема «горизонтальные уровни» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «горизонтальные уровни» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Горизонтальные уровни». Какое действие здесь является главным нарушением логики темы «горизонтальные уровни»?","options":[{"value":"A","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно горизонтальные уровни перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «горизонтальные уровни» в уроке «Горизонтальные уровни»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Горизонтальный уровень в уроке рассматривается как область повторной реакции цены, а не как идеально точная линия.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='technical-horizontal-levels';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Уровни — это зоны, а не линии». Ситуация: Цена немного проколола край зоны, после чего появилась реакция внутри той же области. Что из перечисленного лучше всего соответствует теме «уровни как зоны»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"продолжить оценивать зону по реакции и сценарию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону."},{"id":"q2","type":"multi_select","question":"В уроке «Уровни — это зоны, а не линии» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"продолжить оценивать зону по реакции и сценарию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «уровни как зоны» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Уровни — это зоны, а не линии». Для темы «уровни как зоны» можно пропустить проверку ситуации, если уже выполнено условие: продолжить оценивать зону по реакции и сценарию.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «уровни как зоны» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Уровни — это зоны, а не линии». Какое действие здесь является главным нарушением логики темы «уровни как зоны»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно уровни как зоны перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «уровни как зоны» в уроке «Уровни — это зоны, а не линии»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Поддержку и сопротивление в уроке предлагается воспринимать как зоны, а не как математически точные линии.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='technical-levels-zones';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Order Block». Ситуация: После участка цены началось сильное движение, и трейдер хочет сразу назвать исходную область Order Block. Что из перечисленного лучше всего соответствует теме «Order Block»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала разобрать движение до и после области и условие подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"использовать область без проверки контекста","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования."},{"id":"q2","type":"multi_select","question":"В уроке «Order Block» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"использовать область без проверки контекста","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала разобрать движение до и после области и условие подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «Order Block» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Order Block». Если выполнить условие «сначала разобрать движение до и после области и условие подтверждения», тема «Order Block» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Order Block» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Order Block». Какое действие здесь является главным нарушением логики темы «Order Block»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"использовать область без проверки контекста","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно Order Block перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Order Block» в уроке «Order Block»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В уроке Order Block решение разбирается последовательно: что наблюдаем, что это означает, какое условие должно появиться и когда лучше пропустить.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='tools-order-block';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Order Flow». Ситуация: Цена почти не растёт, хотя давление покупателей заметно усиливается. Что из перечисленного лучше всего соответствует теме «Order Flow»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сравнить изменение давления с реакцией цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены."},{"id":"q2","type":"multi_select","question":"В уроке «Order Flow» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сравнить изменение давления с реакцией цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «Order Flow» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Order Flow». Для темы «Order Flow» можно пропустить проверку ситуации, если уже выполнено условие: сравнить изменение давления с реакцией цены.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Order Flow» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Order Flow». Какое действие здесь является главным нарушением логики темы «Order Flow»?","options":[{"value":"A","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Order Flow перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Order Flow» в уроке «Order Flow»?","options":[{"value":"A","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В уроке Order Flow важен анализ изменения давления покупателей и продавцов вместе с движением цены.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='tools-order-flow';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Fair Value Gap». Ситуация: После импульса цена возвращается к области, которую трейдер отметил как FVG. Что из перечисленного лучше всего соответствует теме «Fair Value Gap»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценить формирование области и реакцию цены при возврате","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"входить автоматически при первом касании области","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении."},{"id":"q2","type":"multi_select","question":"В уроке «Fair Value Gap» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить автоматически при первом касании области","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"оценить формирование области и реакцию цены при возврате","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Fair Value Gap» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Fair Value Gap». Для темы «Fair Value Gap» можно пропустить проверку ситуации, если уже выполнено условие: оценить формирование области и реакцию цены при возврате.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Fair Value Gap» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Fair Value Gap». Какое действие здесь является главным нарушением логики темы «Fair Value Gap»?","options":[{"value":"A","label":"проверить именно Fair Value Gap перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить автоматически при первом касании области","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Fair Value Gap» в уроке «Fair Value Gap»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В уроке Fair Value Gap область нужно оценивать через её формирование и реакцию цены при возвращении.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='tools-fair-value-gap';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Индикаторы для уверенной торговли». Ситуация: RSI показывает интересную зону, но структура цены не подтверждает сценарий. Что из перечисленного лучше всего соответствует теме «индикаторы для уверенной торговли»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"использовать показание индикатора как часть решения, а не как кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить только по показанию RSI","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: MACD, Stochastic, Awesome Oscillator, RSI и Momentum дают разные типы информации и не заменяют контекст."},{"id":"q2","type":"multi_select","question":"В уроке «Индикаторы для уверенной торговли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"MACD, Stochastic, Awesome Oscillator, RSI и Momentum дают разные типы информации и не заменяют контекст","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать показание индикатора как часть решения, а не как кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"входить только по показанию RSI","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «индикаторы для уверенной торговли» и описанной ситуацией, а не с общим впечатление