update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Stochastic». Ситуация: Stochastic дал сигнал на незакрытой свече внутри сильного тренда. Что из перечисленного лучше всего соответствует теме «Stochastic»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"дождаться закрытия свечи и оценить сигнал относительно тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда."},{"id":"q2","type":"multi_select","question":"В уроке «Stochastic» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"дождаться закрытия свечи и оценить сигнал относительно тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Stochastic» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Stochastic». Если выполнить условие «дождаться закрытия свечи и оценить сигнал относительно тренда», тема «Stochastic» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Stochastic» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Stochastic». Какое действие здесь является главным нарушением логики темы «Stochastic»?","options":[{"value":"A","label":"проверить именно Stochastic перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Stochastic» в уроке «Stochastic»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В исходном материале Stochastic задан K14, D3, slowing3 и уровнями 20/80.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='indicators-stochastic';
