update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «SuperTrend + Moving Average». Ситуация: SuperTrend и MA указывают вверх, но цена находится в слабой структуре без продолжения. Что из перечисленного лучше всего соответствует теме «SuperTrend + Moving Average»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить, подтверждается ли согласованный сигнал поведением цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании."},{"id":"q2","type":"multi_select","question":"В уроке «SuperTrend + Moving Average» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"проверить, подтверждается ли согласованный сигнал поведением цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «SuperTrend + Moving Average» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «SuperTrend + Moving Average». Для темы «SuperTrend + Moving Average» можно пропустить проверку ситуации, если уже выполнено условие: проверить, подтверждается ли согласованный сигнал поведением цены.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «SuperTrend + Moving Average» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «SuperTrend + Moving Average». Какое действие здесь является главным нарушением логики темы «SuperTrend + Moving Average»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно SuperTrend + Moving Average перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «SuperTrend + Moving Average» в уроке «SuperTrend + Moving Average»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Связка SuperTrend + Moving Average использует SuperTrend для направления, а Moving Average для краткосрочной динамики.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='strategies-supertrend-ma';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Donchian Channel». Ситуация: На M1 цена подходит к верхней границе Donchian после длительного движения внутри диапазона. Что из перечисленного лучше всего соответствует теме «Donchian Channel»?","options":[{"value":"A","label":"оценить, происходит ли реальный выход из диапазона","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты."},{"id":"q2","type":"multi_select","question":"В уроке «Donchian Channel» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценить, происходит ли реальный выход из диапазона","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «Donchian Channel» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Donchian Channel». Если выполнить условие «оценить, происходит ли реальный выход из диапазона», тема «Donchian Channel» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Donchian Channel» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Donchian Channel». Какое действие здесь является главным нарушением логики темы «Donchian Channel»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно Donchian Channel перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Donchian Channel» в уроке «Donchian Channel»?","options":[{"value":"A","label":"В исходном материале Donchian использует период 22, M1 и экспирацию 1–2 минуты.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='strategies-donchian';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Стратегия Александра». Ситуация: Bollinger и RSI дают разные намёки, а EMA не подтверждает направление. Что из перечисленного лучше всего соответствует теме «стратегия Александра»?","options":[{"value":"A","label":"не считать набор разрозненных сигналов согласованной схемой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"входить потому, что хотя бы один индикатор дал сигнал","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: связка использует Bollinger 20/2, RSI и EMA; смысл — совместно читать цену, волатильность и импульс."},{"id":"q2","type":"multi_select","question":"В уроке «Стратегия Александра» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить потому, что хотя бы один индикатор дал сигнал","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"не считать набор разрозненных сигналов согласованной схемой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"связка использует Bollinger 20/2, RSI и EMA; смысл — совместно читать цену, волатильность и импульс","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «стратегия Александра» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","quest