update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Schaff Trend Cycle + Donchian Channel». Ситуация: Schaff показывает изменение импульса, а цена одновременно находится у границы Donchian. Что из перечисленного лучше всего соответствует теме «Schaff Trend Cycle + Donchian Channel»?","options":[{"value":"A","label":"сопоставить состояние импульса с положением цены в диапазоне","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"рассматривать оба индикатора как два одинаковых сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: Schaff оценивает состояние трендового импульса, Donchian — положение относительно экстремумов диапазона."},{"id":"q2","type":"multi_select","question":"В уроке «Schaff Trend Cycle + Donchian Channel» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"рассматривать оба индикатора как два одинаковых сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Schaff оценивает состояние трендового импульса, Donchian — положение относительно экстремумов диапазона","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сопоставить состояние импульса с положением цены в диапазоне","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Schaff Trend Cycle + Donchian Channel»