update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Moving Average + Fractals». Ситуация: Fractal появился против текущего направления, которое уверенно показывает MA. Что из перечисленного лучше всего соответствует теме «Moving Average + Fractals»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценить fractal внутри контекста направления MA","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики."},{"id":"q2","type":"multi_select","question":"В уроке «Moving Average + Fractals» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценить fractal внутри контекста направления MA","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «Moving Average + Fractals» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Moving Average + Fractals». Для темы «Moving Average + Fractals» можно пропустить проверку ситуации, если уже выполнено условие: оценить fractal внутри контекста направления MA.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Moving Average + Fractals» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Moving Average + Fractals». Какое действие здесь является главным нарушением логики темы «Moving Average + Fractals»?","options":[{"value":"A","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Moving Average + Fractals перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Moving Average + Fractals» в уроке «Moving Average + Fractals»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Moving Average задаёт контекст направления, а Fractals показывают локальные экстремумы, которые нужно оценивать внутри этого контекста.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='strategies-ma-fractals';
