update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «2-of-3». Ситуация: Есть зелёная–красная–зелёная, но третья свеча ещё не закрылась и её максимум ниже первой зелёной. Что из перечисленного лучше всего соответствует теме «2-of-3»?","options":[{"value":"A","label":"считать паттерн готовым до закрытия третьей свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ждать полного закрытия третьей свечи и проверки условия максимума","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: последовательность зелёная–красная–зелёная; третья зелёная закрывается на уровне/выше максимума первой; 30 секунд и 2 минуты."},{"id":"q2","type":"multi_select","question":"В уроке «2-of-3» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать паттерн готовым до закрытия третьей свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"последовательность зелёная–красная–зелёная; третья зелёная закрывается на уровне/выше максимума первой; 30 секунд и 2 минуты","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"ждать полного закрытия третьей свечи и проверки условия максимума","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «2-of-3» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","