update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Психология трейдинга — база». Ситуация: После нескольких неудачных сделок трейдер хочет немедленно увеличить размер следующей позиции. Что из перечисленного лучше всего соответствует теме «психология трейдинга — база»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"остановиться и проверить эмоциональную причину решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: нужно замечать собственные реакции до того, как они превращаются в решение."},{"id":"q2","type":"multi_select","question":"В уроке «Психология трейдинга — база» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"остановиться и проверить эмоциональную причину решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"нужно замечать собственные реакции до того, как они превращаются в решение","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «психология трейдинга — база» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Психология трейдинга — база». Для темы «психология трейдинга — база» можно пропустить проверку ситуации, если уже выполнено условие: остановиться и проверить эмоциональную причину решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «психология трейдинга — база» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Психология трейдинга — база». Какое действие здесь является главным нарушением логики темы «психология трейдинга — база»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно психология трейдинга — база перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: нужно замечать собственные реакции до того, как они превращаются в решение."}]$$::jsonb, true), updated_at=now() where slug='psychology-sixth-live';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Ситуация: Трейдер говорит, что контролирует эмоции, но после убытка постоянно меняет правила входа. Что из перечисленного лучше всего соответствует теме «психология трейдинга — главный принцип»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценивать психологию по фактическим действиям","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой."},{"id":"q2","type":"multi_select","question":"В уроке «Психология трейдинга | Урок 1: главный принцип» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценивать психологию по фактическим действиям","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «психология трейдинга — главный принцип» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Если выполнить условие «оценивать психологию по фактическим действиям», тема «психология трейдинга — главный принцип» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «психология трейдинга — главный принцип» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Какое действие здесь является главным нарушением логики темы «психология трейдинга — главный принцип»?","options":[{"value":"A","label":"проверить именно психология трейдинга — главный принцип перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой."}]$$::jsonb, true), updated_at=now() where slug='psychology-main-principle';
