update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как подбирать время экспирации для сделки?». Ситуация: Сильный импульс и боковой рынок дают разные темпы движения, но трейдер использует одинаковую экспирацию. Что из перечисленного лучше всего соответствует теме «время экспирации»?","options":[{"value":"A","label":"подбирать срок под характер движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением."},{"id":"q2","type":"multi_select","question":"В уроке «Как подбирать время экспирации для сделки?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"подбирать срок под характер движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «время экспирации» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как подбирать время экспирации для сделки?». Если выполнить условие «подбирать срок под характер движения», тема «время экспирации» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «время экспирации» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как подбирать время экспирации для сделки?». Какое действие здесь является главным нарушением логики темы «время экспирации»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно время экспирации перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением."}]$$::jsonb, true), updated_at=now() where slug='timing-expiration';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Торговля по интуиции». Ситуация: Трейдер говорит «чувствую вход», но не может назвать ни одного наблюдаемого признака. Что из перечисленного лучше всего соответствует теме «торговля по интуиции»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разложить ощущение на конкретные признаки и проверить их","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки."},{"id":"q2","type":"multi_select","question":"В уроке «Торговля по интуиции» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разложить ощущение на конкретные признаки и проверить их","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «торговля по интуиции» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Торговля по интуиции». Для темы «торговля по интуиции» можно пропустить проверку ситуации, если уже выполнено условие: разложить ощущение на конкретные признаки и проверить их.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «торговля по интуиции» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Торговля по интуиции». Какое действие здесь является главным нарушением логики темы «торговля по интуиции»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно торговля по интуиции перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки."}]$$::jsonb, true), updated_at=now() where slug='practice-intuition';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Итоги недели — разбор ошибок». Ситуация: Стратегия дала минус, но запись показывает, что вход был сделан вне правил после эмоциональной серии. Что из перечисленного лучше всего соответствует теме «итоги недели и разбор ошибок»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отнести проблему к процессу исполнения, а не автоматически к стратегии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат."},{"id":"q2","type":"multi_select","question":"В уроке «Итоги недели — разбор ошибок» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отнести проблему к процессу исполнения, а не автоматически к стратегии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «итоги недели и разбор ошибок» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Итоги недели — разбор ошибок». Если выполнить условие «отнести проблему к процессу исполнения, а не автоматически к стратегии», тема «итоги недели и разбор ошибок» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «итоги недели и разбор ошибок» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Итоги недели — разбор ошибок». Какое действие здесь является главным нарушением логики темы «итоги недели и разбор ошибок»?","options":[{"value":"A","label":"проверить именно итоги недели и разбор ошибок перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат."}]$$::jsonb, true), updated_at=now() where slug='trade-review-week-errors';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Разбор рынка — 15.07.2025». Ситуация: В разборе разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разбор рынка»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: контекст нужно оценивать до входа."},{"id":"q2","type":"multi_select","question":"В уроке «Разбор рынка — 15.07.2025» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"контекст нужно оценивать до входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «разбор рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Разбор рынка — 15.07.2025». Для темы «разбор рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «разбор рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Разбор рынка — 15.07.2025». Какое действие здесь является главным нарушением логики темы «разбор рынка»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно разбор рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: контекст нужно оценивать до входа."}]$$::jsonb, true), updated_at=now() where slug='market-15072025';
