update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Волатильность». Ситуация: В разборе волатильность трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «волатильность»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: изменение интенсивности движения влияет на то, как нужно оценивать ситуацию."},{"id":"q2","type":"multi_select","question":"В уроке «Волатильность» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменение интенсивности движения влияет на то, как нужно оценивать ситуацию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «волатильность» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","ty