update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Нормальная точка входа». Ситуация: В разборе нормальная точка входа трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «нормальная точка входа»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: вход должен появляться после понятной реакции и подтверждения, а не из-за спешки."},{"id":"q2","type":"multi_select","question":"В уроке «Нормальная точка входа» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"вход должен появляться после понятной реакции и подтверждения, а не из-за спешки","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «нормальная точка входа» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Нормальная точка входа». Для темы «нормальная точка входа» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «нормальная точка входа» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Нормальная точка входа». Какое действие здесь является главным нарушением логики темы «нормальная точка входа»?","options":[{"value":"A","label":"проверить именно нормальная точка входа перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: вход должен появляться после понятной реакции и подтверждения, а не из-за спешки."}]$$::jsonb, true), updated_at=now() where slug='market-normal-entry';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Ликвидность». Ситуация: В разборе ликвидность трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «ликвидность»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: анализ ликвидности нужен как часть контекста движения, а не как отдельный повод нажать кнопку."},{"id":"q2","type":"multi_select","question":"В уроке «Ликвидность» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"анализ ликвидности нужен как часть контекста движения, а не как отдельный повод нажать кнопку","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «ликвидность» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Ликвидность». Для темы «ликвидность» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «ликвидность» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Ликвидность». Какое действие здесь является главным нарушением логики темы «ликвидность»?","options":[{"value":"A","label":"проверить именно ликвидность перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: анализ ликвидности нужен как часть контекста движения, а не как отдельный повод нажать кнопку."}]$$::jsonb, true), updated_at=now() where slug='market-liquidity';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Сила покупателей и продавцов без индикаторов». Ситуация: В разборе сила покупателей и продавцов трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «сила покупателей и продавцов»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: баланс сторон можно оценивать по поведению цены без обязательной опоры на индикатор."},{"id":"q2","type":"multi_select","question":"В уроке «Сила покупателей и продавцов без индикаторов» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"баланс сторон можно оценивать по поведению цены без обязательной опоры на индикатор","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «сила покупателей и продавцов» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Сила покупателей и продавцов без индикаторов». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «сила покупателей и продавцов» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «сила покупателей и продавцов» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Сила покупателей и продавцов без индикаторов». Какое действие здесь является главным нарушением логики темы «сила покупателей и продавцов»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно сила покупателей и продавцов перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: баланс сторон можно оценивать по поведению цены без обязательной опоры на индикатор."}]$$::jsonb, true), updated_at=now() where slug='market-buyers-sellers';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как начать анализ рынка». Ситуация: В разборе начало анализа рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «начало анализа рынка»?","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: анализ полезно строить последовательно: контекст → зона/состояние → реакция → сценарий → подтверждение."},{"id":"q2","type":"multi_select","question":"В уроке «Как начать анализ рынка» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"анализ полезно строить последовательно: контекст → зона/состояние → реакция → сценарий → подтверждение","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «на