update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как я анализирую рынок?». Ситуация: В разборе анализ рынка Амиром трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «анализ рынка Амиром»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата."},{"id":"q2","type":"multi_select","question":"В уроке «Как я анализирую рынок?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «анализ рынка Амиром» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я анализирую рынок?». Для темы «анализ рынка Амиром» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «анализ рынка Амиром» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я анализирую рынок?». Какое действие здесь является главным нарушением логики темы «анализ рынка Амиром»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно анализ рынка Амиром перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата."}]$$::jsonb, true), updated_at=now() where slug='market-how-amir-analyzes';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Какой таймфрейм выбрать новичку?». Ситуация: В разборе таймфрейм для новичка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «таймфрейм для новичка»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план."},{"id":"q2","type":"multi_select","question":"В уроке «Какой таймфрейм выбрать новичку?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «таймфрейм для новичка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Какой таймфрейм выбрать новичку?». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «таймфрейм для новичка» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «таймфрейм для новичка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Какой таймфрейм выбрать новичку?». Какое действие здесь является главным нарушением логики темы «таймфрейм для новичка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно таймфрейм для новичка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план."}]$$::jsonb, true), updated_at=now() where slug='market-beginner-tf';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Почему цена разворачивается от уровня?». Ситуация: В разборе разворот от уровня трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разворот от уровня»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание."},{"id":"q2","type":"multi_select","question":"В уроке «Почему цена разворачивается от уровня?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «разворот от уровня» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Почему цена разворачивается от уровня?». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «разворот от уровня» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «разворот от уровня» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Почему цена разворачивается от уровня?». Какое действие здесь является главным нарушением логики темы «разворот от уровня»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно разворот от уровня перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание."}]$$::jsonb, true), updated_at=now() where slug='market-reversal-level';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Фейк-пробой, импульс и откат». Ситуация: В разборе фейк-пробой, импульс и откат трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «фейк-пробой, импульс и откат»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: выход за уровень может оказаться фейк-пробоем; важна реакция после выхода."},{"id":"q2","type":"multi_select","question":"В уроке «Фейк-пробой, импульс и откат» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"выход за уровень может оказаться фейк-пробоем; важна реакция после выхода","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «фейк-пробой, импульс и откат» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Фейк-пробой, импульс и откат». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «фейк-пробой, импульс и откат» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «фейк-пробой, импульс и откат» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Фейк-пробой, импульс и откат». Какое действие здесь является главным нарушением логики темы «фейк-пробой, импульс и откат»?","options":[{"value":"A","label":"проверить именно фейк-пробой, импульс и откат перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: выход за уровень может оказаться фейк-пробоем; важна реакция после выхода."}]$$::jsonb, true), updated_at=now() where slug='market-false-breakout';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как понять, куда движется рынок?». Ситуация: В разборе направление рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «направление рынка»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: направление определяется последовательностью и контекстом движения, а не одной свечой."},{"id":"q2","type":"multi_select","question":"В уроке «Как понять, куда движется рынок?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"направление определяется последовательностью и контекстом движения, а не одной свечой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «направление рынка» и опи