update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как я анализирую рынок — полный разбор». Ситуация: В разборе полный разбор анализа рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «полный разбор анализа рынка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: ценность полного разбора — последовательная проверка контекста до решения."},{"id":"q2","type":"multi_select","question":"В уроке «Как я анализирую рынок — полный разбор» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ценность полного разбора — последовательная проверка контекста до решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «полный разбор анализа рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я анализирую рынок — полный разбор». Для темы «полный разбор анализа рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «полный разбор анализа рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я анализирую рынок — полный разбор». Какое действие здесь является главным нарушением логики темы «полный разбор анализа рынка»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно полный разбор анализа рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: ценность полного разбора — последовательная проверка контекста до решения."}]$$::jsonb, true), updated_at=now() where slug='market-analysis-duplicate';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Важность долгосрочной прибыли». Ситуация: После двух плюсов трейдер хочет нарушить лимит риска ради более крупной прибыли. Что из перечисленного лучше всего соответствует теме «долгосрочная прибыль»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сохранить правило риска и оценивать результат на серии сделок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важнее качество серии решений, чем попытка получить максимум от одной сделки."},{"id":"q2","type":"multi_select","question":"В уроке «Важность долгосрочной прибыли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"важнее качество серии решений, чем попытка получить максимум от одной сделки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранить правило риска и оценивать результат на серии сделок","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «долгосрочная прибыль» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Важность долгосрочной прибыли». Для темы «долгосрочная прибыль» можно пропустить проверку ситуации, если уже выполнено условие: сохранить правило риска и оценивать результат на серии сделок.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «долгосрочная прибыль» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Важность долгосрочной прибыли». Какое действие здесь является главным нарушением логики темы «долгосрочная прибыль»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно долгосрочная прибыль перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важнее качество серии решений, чем попытка получить максимум от одной сделки."}]$$::jsonb, true), updated_at=now() where slug='money-long-term-profit';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Концепция работы в Amir Family Exclusive». Ситуация: Ученик пытается превратить название программы в конкретный торговый сигнал. Что из перечисленного лучше всего соответствует теме «Amir Family Exclusive»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изучать концепцию через наблюдаемые правила и условия","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа."},{"id":"q2","type":"multi_select","question":"В уроке «Концепция работы в Amir Family Exclusive» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изучать концепцию через наблюдаемые правила и условия","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «Amir Family Exclusive» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Концепция работы в Amir Family Exclusive». Для темы «Amir Family Exclusive» можно пропустить проверку ситуации, если уже выполнено условие: изучать концепцию через наблюдаемые правила и условия.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Amir Family Exclusive» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Концепция работы в Amir Family Exclusive». Какое действие здесь является главным нарушением логики темы «Amir Family Exclusive»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно Amir Family Exclusive перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа."}]$$::jsonb, true), updated_at=now() where slug='advanced-amir-family';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как понять, когда не стоит торговать?». Ситуация: На рынке нет понятного сценария, но трейдер хочет войти ради активности. Что из перечисленного лучше всего соответствует теме «когда не стоит торговать»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"пропустить ситуацию без достаточных условий","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: отказ от сделки — часть системы управления качеством решений."},{"id":"q2","type":"multi_select","question":"В уроке «Как понять, когда не стоит торговать?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"отказ от сделки — часть системы управления качеством решений","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"пропустить ситуацию без достаточных условий","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «когда не стоит торговать» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как понять, когда не стоит торговать?». Если выполнить условие «пропустить ситуацию без достаточных условий», тема «когда не стоит торговать» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «когда не стоит торговать» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как понять, когда не стоит торговать?». Какое действие здесь является главным нарушением логики темы «когда не стоит торговать»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно когда не стоит торговать перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: отказ от сделки — часть системы управления качеством решений."}]$$::jsonb, true), updated_at=now() where slug='money-when-not-trade';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как я постоянно выхожу в плюс?». Ситуация: После одного убытка трейдер меняет стратегию, чтобы следующая сделка обязательно была плюсовой. Что из перечисленного лучше всего соответствует теме «постоянный плюс»?","options":[{"value":"A","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранять проверяемый процесс и оценивать серию","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: системность важнее попытки гарантировать плюс каждой отдельной сделкой."},{"id":"q2","type":"multi_select","question":"В уроке «Как я постоянно выхожу в плюс?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сохранять проверяемый процесс и оценивать серию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"системность важнее попытки гарантировать плюс каждой отдельной сделкой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «постоянный плюс» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я постоянно выхожу в плюс?». Для темы «постоянный плюс» можно пропустить проверку ситуации, если уже выполнено условие: сохранять проверяемый процесс и оценивать серию.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «постоянный плюс» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я постоянно выхожу в плюс?». Какое действие здесь является главным нарушением логики темы «постоянный плюс»?","options":[{"value":"A","label":"проверить именно постоянный плюс перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: системность важнее попытки гарантировать плюс каждой отдельной сделкой."}]$$::jsonb, true), updated_at=now() where slug='money-constantly-profit';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Трейдинг начинается в голове — урок 1». Ситуация: Трейдер видит хороший сигнал, но находится в состоянии после серии эмоциональных решений. Что из перечисленного лучше всего соответствует теме «трейдинг начинается в голове»?","options":[{"value":"A","label":"сначала оценить состояние и готовность соблюдать правила","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: решение начинается с состояния и правил трейдера до открытия позиции."},{"id":"q2","type":"multi_select","question":"В уроке «Трейдинг начинается в голове — урок 1» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала оценить состояние и готовность соблюдать правила","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"решение начинается с состояния и правил трейдера до открытия позиции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «трейдинг начинается в голове» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Трейдинг начинается в голове — урок 1». Если выполнить условие «сначала оценить состояние и готовность соблюдать правила», тема «трейдинг начинается в голове» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «трейдинг начинается в голове» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Трейдинг начинается в голове — урок 1». Какое действие здесь является главным нарушением логики темы «трейдинг начинается в голове»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно трейдинг начинается в голове перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: решение начинается с состояния и правил трейдера до открытия позиции."}]$$::jsonb, true), updated_at=now() where slug='psychology-trading-starts-head';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как зарабатывать много с минимальными рисками?». Ситуация: Чтобы быстрее заработать, трейдер предлагает резко увеличить размер позиции при том же качестве сигнала. Что из перечисленного лучше всего соответствует теме «много с минимальными рисками»?","options":[{"value":"A","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранять контролируемый риск и искать качество решений","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки."},{"id":"q2","type":"multi_select","question":"В уроке «Как зарабатывать много с минимальными рисками?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сохранять контролируемый риск и искать качество решений","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «много с минимальными рисками» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как зарабатывать много с минимальными рисками?». Для темы «много с минимальными рисками» можно пропустить проверку ситуации, если уже выполнено условие: сохранять контролируемый риск и искать качество решений.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «много с минимальными рисками» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как зарабатывать много с минимальными рисками?». Какое действие здесь является главным нарушением логики темы «много с минимальными рисками»?","options":[{"value":"A","label":"проверить именно много с минимальными рисками перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки."}]$$::jsonb, true), updated_at=now() where slug='money-minimal-risks';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как торгует Амир?». Ситуация: Ученик видит успешную сделку Амирa и хочет повторить только направление сделки. Что из перечисленного лучше всего соответствует теме «как торгует Амир»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разобрать причины и последовательность решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение."},{"id":"q2","type":"multi_select","question":"В уроке «Как торгует Амир?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разобрать причины и последовательность решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «как торгует Амир» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как торгует Амир?». Для темы «как торгует Амир» можно пропустить проверку ситуации, если уже выполнено условие: разобрать причины и последовательность решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «как торгует Амир» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как торгует Амир?». Какое действие здесь является главным нарушением логики темы «как торгует Амир»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно как торгует Амир перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение."}]$$::jsonb, true), updated_at=now() where slug='advanced-how-amir-trades';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Как торгует Амир? — Часть 2». Ситуация: Ученик запомнил результат сделки, но не может объяснить условия её открытия. Что из перечисленного лучше всего соответствует теме «как торгует Амир — часть 2»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"вернуться к условиям и логике решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов."},{"id":"q2","type":"multi_select","question":"В уроке «Как торгует Амир? — Часть 2» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"вернуться к условиям и логике решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «как торгует Амир — часть 2» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как торгует Амир? — Часть 2». Если выполнить условие «вернуться к условиям и логике решения», тема «как торгует Амир — часть 2» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «как торгует Амир — часть 2» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как торгует Амир? — Часть 2». Какое действие здесь является главным нарушением логики темы «как торгует Амир — часть 2»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно как торгует Амир — часть 2 перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов."}]$$::jsonb, true), updated_at=now() where slug='advanced-how-amir-trades-2';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Книга «Зональный трейдинг»». Ситуация: Цена немного вышла за границу зоны, но реакция сохраняется внутри области. Что из перечисленного лучше всего соответствует теме «книга «Зональный трейдинг»»?","options":[{"value":"A","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценивать зону как область с контекстом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку."},{"id":"q2","type":"multi_select","question":"В уроке «Книга «Зональный трейдинг»» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценивать зону как область с контекстом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «книга «Зональный трейдинг»» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Книга «Зональный трейдинг»». Для темы «книга «Зональный трейдинг»» можно пропустить проверку ситуации, если уже выполнено условие: оценивать зону как область с контекстом.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «книга «Зональный трейдинг»» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Книга «Зональный трейдинг»». Какое действие здесь является главным нарушением логики темы «книга «Зональный трейдинг»»?","options":[{"value":"A","label":"проверить именно книга «Зональный трейдинг» перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку."}]$$::jsonb, true), updated_at=now() where slug='advanced-zone-trading-book';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Forex: кто двигает цену?». Ситуация: Цена движется, и трейдер пытается объяснить движение только показанием одного осциллятора. Что из перечисленного лучше всего соответствует теме «Forex: кто двигает цену»?","options":[{"value":"A","label":"рассматривать движение через рыночный контекст и взаимодействие сторон","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору."},{"id":"q2","type":"multi_select","question":"В уроке «Forex: кто двигает цену?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"рассматривать движение через рыночный контекст и взаимодействие сторон","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Forex: кто двигает цену» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Forex: кто двигает цену?». Если выполнить условие «рассматривать движение через рыночный контекст и взаимодействие сторон», тема «Forex: кто двигает цену» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Forex: кто двигает цену» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Forex: кто двигает цену?». Какое действие здесь является главным нарушением логики темы «Forex: кто двигает цену»?","options":[{"value":"A","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Forex: кто двигает цену перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору."}]$$::jsonb, true), updated_at=now() where slug='advanced-forex-market';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Новое обучение аналитика — личная стратегия». Ситуация: Две одинаково выглядящие сделки получают разные решения без изменения условий. Что из перечисленного лучше всего соответствует теме «личная стратегия аналитика»?","options":[{"value":"A","label":"уточнить критерии стратегии и сделать их проверяемыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять."},{"id":"q2","type":"multi_select","question":"В уроке «Новое обучение аналитика — личная стратегия» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"уточнить критерии стратегии и сделать их проверяемыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «личная стратегия аналитика» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Новое обучение аналитика — личная стратегия». Если выполнить условие «уточнить критерии стратегии и сделать их проверяемыми», тема «личная стратегия аналитика» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «личная стратегия аналитика» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Новое обучение аналитика — личная стратегия». Какое действие здесь является главным нарушением логики темы «личная стратегия аналитика»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно личная стратегия аналитика перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять."}]$$::jsonb, true), updated_at=now() where slug='advanced-personal-strategy-training';
update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Первая эксклюзивная сессия». Ситуация: Во время «Первая эксклюзивная сессия» запись ещё не дошла до решения, но ученик хочет сразу посмотреть результат. Что из перечисленного лучше всего соответствует теме «Первая эксклюзивная сессия»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок."},{"id":"q2","type":"multi_select","question":"В уроке «Первая эксклюзивная сессия» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Све