update public.learning_lessons set content=jsonb_set(coalesce(content,'{}'::jsonb), '{quiz}', $$[{"id":"q1","type":"single_select","question":"Урок «Top 3 индикатора, Top 3 ошибки и самотест трейдера». Ситуация: Трейдер после серии побед начинает увеличивать риск и одновременно перестаёт проверять ликвидность. Что из перечисленного лучше всего соответствует теме «Top 3 индикатора, Top 3 ошибки и самотест трейдера»?","options":[{"value":"A","label":"считать серию побед доказательством, что дополнительные проверки больше не нужны","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"распознать обе ошибки и вернуть проверяемый процесс","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: урок связывает RSI/MACD/Keltner с ошибками: объём/ликвидность, самоуверенность после побед и зависимость от одного таймфрейма/актива."},{"id":"q2","type":"multi_select","question":"В уроке «Top 3 индикатора, Top 3 ошибки и самотест трейдера» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"урок связывает RSI/MACD/Keltner с ошибками: объём/ликвидность, самоуверенность после побед и зависимость от одного таймфрейма/актива","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать серию побед доказательством, что дополнительные проверки больше не нужны","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"распознать обе ошибки и вернуть проверяемый процесс","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «Top 3 индикатора, Top 3 ошибки и самотест трейдера» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Top 3 индикатора, Top 3 ошибки и самотест трейдера». Для темы «Top 3 индикатора, Top 3 ошибки и самотест трейдера» можно пропустить проверку ситуации, если уже выполнено условие: распознать обе ошибки и вернуть проверяемый процесс.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Top 3 индикатора, Top 3 ошибки и самотест трейдера» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Top 3 индикатора, Top 3 ошибки и самотест трейдера». Какое действие здесь является главным нарушением логики темы «Top 3 индикатора, Top 3 ошибки и самотест трейдера»?","options":[{"value":"A","label":"проверить именно Top 3 индикатора, Top 3 ошибки и самотест трейдера перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать серию побед доказательством, что дополнительные проверки больше не нужны","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: урок связывает RSI/MACD/Keltner с ошибками: объём/ликвидность, самоуверенность после побед и зависимость от одного таймфрейма/актива."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Top 3 индикатора, Top 3 ошибки и самотест трейдера» в уроке «Top 3 индикатора, Top 3 ошибки и самотест трейдера»?","options":[{"value":"A","label":"Практический критерий урока — не заменять условия темы догадкой по одному признаку.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}]$$::jsonb, true), updated_at=now() where slug='patterns-top3-mistakes-selftest';
